class Solution:
    def rotateTheBox(self, box: List[List[str]]) -> List[List[str]]:
        m, n = len(box), len(box[0])
        for i in range(m):
            empty = n - 1
            for j in range(n - 1, -1, -1):
                if box[i][j] == '*':
                    empty = j - 1
                elif box[i][j] == '#':
                    box[i][j] = '.'
                    box[i][empty] = '#'
                    empty -= 1
        result = [[''] * m for _ in range(n)]
        for i in range(m):
            for j in range(n):
                result[j][m - 1 - i] = box[i][j]
        return result

class Solution:
    def sumOfFlooredPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        mx = max(nums)
        cnt = [0] * (mx + 1)
        for x in nums:
            cnt[x] += 1
        prefix = [0] * (mx + 2)
        for i in range(1, mx + 1):
            prefix[i] = prefix[i-1] + cnt[i]
        res = 0
        for x in range(1, mx + 1):
            if cnt[x] == 0:
                continue
            for k in range(1, mx // x + 1):
                lo = k * x
                hi = min((k + 1) * x - 1, mx)
                res += cnt[x] * k * (prefix[hi] - prefix[lo - 1])
        return res % MOD

