class Solution:
    def minSwaps(self, s: str) -> int:
        n = len(s)
        ones = s.count('1')
        zeros = n - ones
        if abs(ones - zeros) > 1:
            return -1
        def count_mismatch(start):
            cnt = 0
            for i, c in enumerate(s):
                expected = str((start + i) % 2)
                if c != expected:
                    cnt += 1
            return cnt // 2
        if ones > zeros:
            return count_mismatch(1)
        elif zeros > ones:
            return count_mismatch(0)
        else:
            return min(count_mismatch(0), count_mismatch(1))

