        for x in nums2:
            self.cnt[x] = self.cnt.get(x, 0) + 1

    def add(self, index: int, val: int) -> None:
        old = self.nums2[index]
        self.cnt[old] -= 1
        self.nums2[index] += val
        new = self.nums2[index]
        self.cnt[new] = self.cnt.get(new, 0) + 1

