class Solution:
    def getBiggestThree(self, grid: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        seen = set()
        import heapq
        heap = []
        for i in range(m):
            for j in range(n):
                val = grid[i][j]
                if val not in seen:
                    seen.add(val)
                    heapq.heappush(heap, val)
                    if len(heap) > 3:
                        seen.discard(heapq.heappop(heap))
                for k in range(1, min(m, n)):
                    if i - k < 0 or i + k >= m or j - k < 0 or j + k >= n:
                        break
                    s = 0
                    for d in range(k):
                        s += grid[i-k+d][j-d]
                        s += grid[i-k+d][j+d]
                        s += grid[i+k-d][j-d]
                        s += grid[i+k-d][j+d]
                    s -= grid[i-k][j] + grid[i+k][j] + grid[i][j-k] + grid[i][j+k]
                    if s not in seen:
                        seen.add(s)
                        heapq.heappush(heap, s)
                        if len(heap) > 3:
                            seen.discard(heapq.heappop(heap))
        return sorted(heap, reverse=True)

class Solution:
    def minimumXORSum(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        dp = [float('inf')] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            i = bin(mask).count('1')
            if i >= n:
                continue
            for j in range(n):
                if mask & (1 << j) == 0:
                    dp[mask | (1 << j)] = min(dp[mask | (1 << j)], dp[mask] + (nums1[i] ^ nums2[j]))
        return dp[(1 << n) - 1]

