class Solution:
    def minSkips(self, dist: List[int], speed: int, hoursBefore: int) -> int:
        import math
        n = len(dist)
        EPS = 1e-9
        dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i in range(1, n + 1):
            t = dist[i-1] / speed
            for j in range(i + 1):
                if j <= i - 1 and dp[i-1][j] < float('inf'):
                    if i < n:
                        dp[i][j] = min(dp[i][j], math.ceil(dp[i-1][j] + t - EPS))
                    else:
                        dp[i][j] = min(dp[i][j], dp[i-1][j] + t)
                if j > 0 and dp[i-1][j-1] < float('inf'):
                    dp[i][j] = min(dp[i][j], dp[i-1][j-1] + t)
        for j in range(n + 1):
            if dp[n][j] <= hoursBefore + EPS:
                return j
        return -1

