class Solution:
    def minWastedSpace(self, packages: List[int], boxes: List[List[int]]) -> int:
        import bisect
        MOD = 10**9 + 7
        packages.sort()
        n = len(packages)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + packages[i]
        res = float('inf')
        for supplier in boxes:
            supplier.sort()
            if supplier[-1] < packages[-1]:
                continue
            waste = 0
            prev = 0
            for box in supplier:
                idx = bisect.bisect_right(packages, box)
                if idx > prev:
                    waste += box * (idx - prev) - (prefix[idx] - prefix[prev])
                prev = idx
            res = min(res, waste)
        return res % MOD if res != float('inf') else -1

