class Solution:
    def largestMagicSquare(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        row = [[0]*(n+1) for _ in range(m)]
        col = [[0]*(m+1) for _ in range(n)]
        for i in range(m):
            for j in range(n):
                row[i][j+1] = row[i][j] + grid[i][j]
                col[j][i+1] = col[j][i] + grid[i][j]
        for k in range(min(m,n), 1, -1):
            for i in range(m-k+1):
                for j in range(n-k+1):
                    target = row[i][j+k] - row[i][j]
                    valid = True
                    for r in range(i, i+k):
                        if row[r][j+k] - row[r][j] != target:
                            valid = False; break
                    if not valid: continue
                    for c in range(j, j+k):
                        if col[c][i+k] - col[c][i] != target:
                            valid = False; break
                    if not valid: continue
                    d1 = sum(grid[i+x][j+x] for x in range(k))
                    d2 = sum(grid[i+x][j+k-1-x] for x in range(k))
                    if d1 == target and d2 == target:
                        return k
        return 1

class Solution:
    def minOperationsToFlip(self, expression: str) -> int:
        stack = []
        for ch in expression:
            if ch == '(' or ch in '&|':
                stack.append(ch)
            else:
                if ch == '0':
                    cur = (0, 1)
                elif ch == '1':
                    cur = (1, 1)
                else:
                    cur = stack.pop()
                    stack.pop()
                while stack and stack[-1] in '&|':
                    op = stack.pop()
                    left = stack.pop()
                    lv, lc = left
                    rv, rc = cur
                    if op == '&':
                        if lv == 0 and rv == 0:
                            cur = (0, min(lc, rc))
                        elif lv == 0 and rv == 1:
                            cur = (0, 1)
                        elif lv == 1 and rv == 0:
                            cur = (0, 1)
                        else:
                            cur = (1, min(lc, rc) + 1)
                    else:
                        if lv == 1 and rv == 1:
                            cur = (1, min(lc, rc))
                        elif lv == 1 and rv == 0:
                            cur = (1, 1)
                        elif lv == 0 and rv == 1:
                            cur = (1, 1)
                        else:
                            cur = (0, min(lc, rc) + 1)
                stack.append(cur)
        return stack[0][1]

