class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        results = set()
        def dfs(players, round_num):
            k = len(players)
            fp = players.index(firstPlayer)
            sp = players.index(secondPlayer)
            if fp + sp == k - 1:
                results.add(round_num)
                return
            pairs = []
            for i in range(k // 2):
                pairs.append((players[i], players[k-1-i]))
            mid = [players[k//2]] if k % 2 else []
            def generate(idx, winners):
                if idx == len(pairs):
                    next_players = sorted(winners + mid)
                    dfs(next_players, round_num + 1)
                    return
                a, b = pairs[idx]
                if a == firstPlayer or a == secondPlayer:
                    generate(idx + 1, winners + [a])
                elif b == firstPlayer or b == secondPlayer:
                    generate(idx + 1, winners + [b])
                else:
                    generate(idx + 1, winners + [a])
                    generate(idx + 1, winners + [b])
            generate(0, [])
        dfs(list(range(1, n+1)), 1)
        return [min(results), max(results)]

class Solution:
    def findPeakGrid(self, mat: List[List[int]]) -> List[int]:
        m, n = len(mat), len(mat[0])
        lo, hi = 0, m - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            max_col = max(range(n), key=lambda j: mat[mid][j])
            up = mat[mid-1][max_col] if mid > 0 else -1
            down = mat[mid+1][max_col] if mid < m-1 else -1
            if mat[mid][max_col] > up and mat[mid][max_col] > down:
                return [mid, max_col]
            elif up > mat[mid][max_col]:
                hi = mid - 1
            else:
                lo = mid + 1
        return [-1, -1]

class Solution:
    def maxDepthBST(self, order: List[int]) -> int:
        from sortedcontainers import SortedList
        sl = SortedList()
        depth = {}
        sl.add(order[0])
        depth[order[0]] = 1
        res = 1
        for val in order[1:]:
            sl.add(val)
            idx = sl.index(val)
            d = 0
            if idx > 0:
                d = max(d, depth[sl[idx-1]])
            if idx < len(sl) - 1:
                d = max(d, depth[sl[idx+1]])
            depth[val] = d + 1
            res = max(res, d + 1)
        return res

