class Solution:
    def numberOfRounds(self, loginTime: str, logoutTime: str) -> int:
        start = int(loginTime[:2]) * 60 + int(loginTime[3:])
        end = int(logoutTime[:2]) * 60 + int(logoutTime[3:])
        if end < start:
