        m, n = len(grid1), len(grid1[0])
        def dfs(i, j):
            if i < 0 or i >= m or j < 0 or j >= n or grid2[i][j] == 0:
                return True
            grid2[i][j] = 0
            res = grid1[i][j] == 1
            for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
