        return count

class Solution:
    def minDifference(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        prefix = [[0]*101 for _ in range(n+1)]
        for i in range(n):
            for v in range(101):
                prefix[i+1][v] = prefix[i][v]
            prefix[i+1][nums[i]] += 1
        res = []
        for l, r in queries:
            prev = -1
            min_diff = float('inf')
            for v in range(1, 101):
                if prefix[r+1][v] - prefix[l][v] > 0:
                    if prev != -1:
                        min_diff = min(min_diff, v - prev)
                    prev = v
            res.append(min_diff if min_diff != float('inf') else -1)
        return res

