class Solution:
    def canBeIncreasing(self, nums: List[int]) -> bool:
        def check(skip):
            prev = -1
            for i in range(len(nums)):
                if i == skip: continue
                if nums[i] <= prev:
                    return False
                prev = nums[i]
            return True
        for i in range(1, len(nums)):
            if nums[i] <= nums[i-1]:
                return check(i) or check(i-1)
        return True

class Solution:
    def removeOccurrences(self, s: str, part: str) -> str:
        stack = []
        for ch in s:
            stack.append(ch)
            if len(stack) >= len(part) and ''.join(stack[-len(part):]) == part:
                del stack[-len(part):]
        return ''.join(stack)

