class Solution:
    def rotateGrid(self, grid: List[List[int]], k: int) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        layers = min(m, n) // 2
        for layer in range(layers):
            r1, c1, r2, c2 = layer, layer, m-1-layer, n-1-layer
            cells = []
            for c in range(c1, c2): cells.append(grid[r1][c])
            for r in range(r1, r2): cells.append(grid[r][c2])
            for c in range(c2, c1, -1): cells.append(grid[r2][c])
            for r in range(r2, r1, -1): cells.append(grid[r][c1])
            L = len(cells)
            shift = k % L
            cells = cells[shift:] + cells[:shift]
            idx = 0
            for c in range(c1, c2): grid[r1][c] = cells[idx]; idx += 1
            for r in range(r1, r2): grid[r][c2] = cells[idx]; idx += 1
            for c in range(c2, c1, -1): grid[r2][c] = cells[idx]; idx += 1
            for r in range(r2, r1, -1): grid[r][c1] = cells[idx]; idx += 1
        return grid

class Solution:
    def wonderfulSubstrings(self, word: str) -> int:
        count = [0] * 1024
        count[0] = 1
        mask = 0
        res = 0
        for ch in word:
            mask ^= 1 << (ord(ch) - ord('a'))
            res += count[mask]
            for i in range(10):
                res += count[mask ^ (1 << i)]
            count[mask] += 1
        return res

class Solution:
    def kthSmallestSubarraySum(self, nums: List[int], k: int) -> int:
        def count_le(target):
            count = 0
            curr_sum = 0
            l = 0
            for r in range(len(nums)):
                curr_sum += nums[r]
                while curr_sum > target:
                    curr_sum -= nums[l]
                    l += 1
                count += r - l + 1
            return count
        lo, hi = min(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if count_le(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def buildArray(self, nums: List[int]) -> List[int]:
        return [nums[nums[i]] for i in range(len(nums))]
